import importlib
import math
import runpy
import sys
import tempfile
from pathlib import Path


def _olvidar(nombre):
    """Borra de la caché el módulo y sus submódulos para importarlos de cero."""
    for clave in list(sys.modules):
        if clave == nombre or clave.startswith(nombre + "."):
            del sys.modules[clave]


def _importar_desde(carpeta, nombre):
    """Importa el módulo buscándolo primero en carpeta, sin usar versiones anteriores de la caché."""
    _olvidar(nombre)
    importlib.invalidate_caches()
    sys.path.insert(0, str(carpeta))
    try:
        return importlib.import_module(nombre)
    finally:
        sys.path.remove(str(carpeta))

