import keyword
from pathlib import Path


def es_nombre_importable(nombre):
    return (
        nombre.isidentifier()
        and not keyword.iskeyword(nombre)
        and not nombre.startswith("_")
    )


def listar_modulos(carpeta):
    nombres = []
    for ruta in Path(carpeta).iterdir():
        if ruta.is_file() and ruta.suffix == ".py":
            nombre = ruta.stem
        elif ruta.is_dir() and (ruta / "__init__.py").is_file():
            nombre = ruta.name
        else:
            continue
        if es_nombre_importable(nombre):
            nombres.append(nombre)
    return sorted(nombres)

