from pathlib import Path


def buscar_modulo(nombre, rutas):
    porciones = []
    for ruta in rutas:
        carpeta = Path(ruta)
        init = carpeta / nombre / "__init__.py"
        if init.is_file():
            return ("paquete", init)
        modulo = carpeta / f"{nombre}.py"
        if modulo.is_file():
            return ("modulo", modulo)
        if (carpeta / nombre).is_dir():
            porciones.append(carpeta / nombre)
    if porciones:
        return ("namespace", porciones)
    return None

