import importlib
import importlib.machinery
import tempfile
from pathlib import Path


def _estructura(*rutas):
    """Crea una carpeta temporal con esas rutas; las que acaban en / son carpetas."""
    base = Path(tempfile.mkdtemp())
    for ruta in rutas:
        destino = base / ruta
        if ruta.endswith("/"):
            destino.mkdir(parents=True, exist_ok=True)
        else:
            destino.parent.mkdir(parents=True, exist_ok=True)
            destino.write_text("X = 1\n", encoding="utf-8")
    return base


def _real(nombre, rutas):
    """La respuesta del buscador real de Python, en el mismo formato."""
    importlib.invalidate_caches()
    spec = importlib.machinery.PathFinder.find_spec(nombre, [str(r) for r in rutas])
    if spec is None:
        return None
    if spec.origin is None:
        return ("namespace", [Path(p) for p in spec.submodule_search_locations])
    if spec.submodule_search_locations is not None:
        return ("paquete", Path(spec.origin))
    return ("modulo", Path(spec.origin))


def _comprobar(nombre, rutas, esperado, base):
    obtenido = buscar_modulo(nombre, rutas)

    def corto(r):
        if r is None:
            return None
        if isinstance(r[1], list):
            return (r[0], [Path(p).relative_to(base).as_posix() for p in r[1]])
        return (r[0], Path(r[1]).relative_to(base).as_posix())

    assert obtenido == esperado, f"buscar_modulo({nombre!r}, …) debía devolver {corto(esperado)} y devolvió {obtenido!r}"
    assert obtenido == _real(nombre, rutas), "Tu resultado no coincide con el del importador real de Python"

