import importlib
from pathlib import Path


def cargar_plugins(paquete):
    importlib.invalidate_caches()
    modulo_paquete = importlib.import_module(paquete)
    carpeta = Path(modulo_paquete.__file__).parent
    plugins = {}
    for archivo in sorted(carpeta.glob("*.py")):
        nombre = archivo.stem
        if nombre.startswith("_"):
            continue
        modulo = importlib.import_module(f"{paquete}.{nombre}")
        if "ejecutar" in dir(modulo):
            plugins[nombre] = modulo.ejecutar
    return plugins

