import random
import statistics
from collections import Counter
from itertools import product


def distribucion_teorica(caras=6):
    caras_dado = range(1, caras + 1)
    conteo = Counter([a + b for a, b in product(caras_dado, repeat=2)])
    total = caras ** 2
    return {suma: round(conteo[suma] / total, 4) for suma in range(2, 2 * caras + 1)}


def tirar_pares(tiradas, semilla, caras=6):
    generador = random.Random(semilla)
    return [generador.randint(1, caras) + generador.randint(1, caras) for _ in range(tiradas)]


def frecuencias(sumas, caras=6):
    conteo = Counter(sumas)
    return {suma: conteo[suma] for suma in range(2, 2 * caras + 1)}


def suma_mas_frecuente(frecs):
    if not frecs:
        return None
    return max(sorted(frecs), key=lambda suma: frecs[suma])


def informe(tiradas, semilla, caras=6):
    sumas = tirar_pares(tiradas, semilla, caras)
    media = statistics.fmean(sumas)
    frecs = frecuencias(sumas, caras)
    teorica = distribucion_teorica(caras)
    error = max([abs(frecs[s] / tiradas - teorica[s]) for s in frecs])
    return {
        "tiradas": tiradas,
        "media": round(media, 3),
        "desviacion": round(statistics.pstdev(sumas), 3),
        "mas_frecuente": suma_mas_frecuente(frecs),
        "error_maximo": round(error, 4),
    }

